import { ABMS_MOC, AOA_OCC, BOARD_TASKS } from "../constants/boardRequirements.js";
import { certBodyOf, isAdvancedPractice, isNuccSpecialtyId } from "../constants/professions.js";
import { isInactive } from "./lifecycle.js";

/**
 * Board continuing-certification compliance — computes standing for every
 * board selected in Settings → Board Specialties, from the same CME entries
 * the state engine uses.
 *
 *  - ABMS boards: annual boards (cycle 1, e.g. ABNS's 20 Cat 1/yr with no
 *    carryover) window on the CALENDAR YEAR; multi-year cycles use a rolling
 *    window (without the certificate's anchor date that's the honest
 *    approximation, and it's labeled as such).
 *  - AOA boards: the AOA CME cycle is a FIXED three-year block
 *    (2022–24, 2025–27, …), with the board's own OCC hours and any
 *    Category 1-A minimum, plus the board's specialty-specific note. A board
 *    with a published first-cycle chart (AOBS) prorates the hours from the
 *    Board Certification record's issued date.
 *  - Subspecialties follow their primary board and render as notes.
 */

// AOA CME cycles are fixed three-year blocks; 2025–2027 is current.
export function aoaCycle(today = new Date()) {
  const y = today.getFullYear();
  const start = y - (((y - 2025) % 3) + 3) % 3;
  return { start, end: start + 2 };
}

// Rounded to hundredths where summed (see compliance.js round2).
const hoursIn = (cme, from, to, pred = () => true) =>
  Math.round(cme
    .filter(c => c.date && c.date >= from && c.date <= to && pred(c))
    .reduce((s, c) => s + (parseFloat(c.hours) || 0), 0) * 100) / 100;

export function computeBoardCompliance(data) {
  const cme = data.cme || [];
  const today = new Date();
  const todayISO = today.toISOString().slice(0, 10);
  const out = [];

  // In the AOA/ABMS structure, disciplines like neurological surgery are
  // certified BY a parent board (AOBS/ABNS). Picking the discipline alone
  // must produce the parent board's full requirement card — a neurosurgeon
  // shouldn't have to know to pick "Surgery".
  const seen = new Set();
  // NUCC specialties (a PA's or NP's specialty or population focus) are not
  // boards and never produce a board card.
  const resolved = (data.settings.specialties || []).filter(id => !isNuccSpecialtyId(id)).map(id => {
    const [kind, code, ...rest] = String(id).split(":");
    const subName = rest.join(":");
    // ABMS subspecialties explicitly follow their primary board. AOA
    // disciplines do NOT get merged into the parent board — a neurosurgery
    // certificate is its own certificate (per Eric), tracked separately.
    if (kind === "ABMS-SUB" && ABMS_MOC[code]) return { id, kind: "ABMS", code, displayName: subName };
    return { id, kind, code, displayName: subName };
  });

  for (const spec of resolved) {
    const { id, kind, code, displayName } = spec;
    const subName = displayName;
    // One card per underlying board, even if both the board and its
    // discipline are selected
    if ((kind === "ABMS" || kind === "AOA") && seen.has(`${kind}:${code}`)) continue;

    if (kind === "ABMS" && ABMS_MOC[code]) {
      seen.add(`ABMS:${code}`);
      const b = ABMS_MOC[code];
      const cycleYears = b.cycle || 1;
      let from, to, windowLabel, daysLeft;
      if (cycleYears === 1) {
        from = `${today.getFullYear()}-01-01`;
        to = todayISO;
        windowLabel = `${today.getFullYear()} (no carryover)`;
        daysLeft = Math.ceil((new Date(`${today.getFullYear()}-12-31T23:59`) - today) / 86400000);
      } else {
        const f = new Date(today);
        f.setFullYear(f.getFullYear() - cycleYears);
        from = f.toISOString().slice(0, 10);
        to = todayISO;
        windowLabel = `rolling ${cycleYears}-year window`;
        daysLeft = null;
      }
      // Count and display through TODAY, not Dec 31: a rolling window that ran
      // to year-end swept in up to a year of future-dated entries, and the
      // annual window counted CME dated later this year that has not happened.
      const earned = hoursIn(cme, from, to,
        c => (c.category || "").includes("AMA PRA Category 1"));
      out.push({
        id, source: "ABMS", code, name: subName || b.name,
        label: `${subName || b.name}, ABMS ${code}`,
        required: b.hours, earned, met: earned >= b.hours,
        unit: b.unit, windowLabel, daysLeft,
        from, to, countRule: "AMA PRA Category 1",
        assessment: b.assessment || "", notes: b.notes || "",
        citation: `ABMS ${code} continuing certification (${b.name})`,
        verified: b.verified || null,
      });
    } else if (kind === "AOA" && AOA_OCC[code]) {
      // Per-board OCC numbers (verified 2026-07): OCC participants /
      // time-limited certs owe the board's timeLimited figure (60 for most
      // boards), NOT the 120 that only applies outside OCC. Category 1-A
      // minimums are per board — many boards, incl. AOBS, have none.
      const b = AOA_OCC[code];
      seen.add(`AOA:${code}`);
      const cyc = aoaCycle(today);
      const { req, firstCycle } = aoaRequirement(b, code, data, id, cyc);
      const from = `${cyc.start}-01-01`, to = `${cyc.end}-12-31`;
      const earned = hoursIn(cme, from, to);
      const cat1a = hoursIn(cme, from, to, c => (c.category || "").includes("AOA Category 1-A"));
      out.push({
        ...(firstCycle ? { firstCycle } : {}),
        id, source: "AOA", code, name: subName || b.name,
        label: `${subName || b.name}, AOA ${code}`,
        from, to, countRule: null,
        required: req.hours, earned,
        met: earned >= req.hours && cat1a >= (req.cat1 || 0),
        cat1aRequired: req.cat1 || 0, cat1aEarned: cat1a,
        unit: "total hrs, all categories (OCC participant)",
        windowLabel: `${cyc.start}–${cyc.end} AOA cycle`,
        daysLeft: Math.ceil((new Date(`${cyc.end}-12-31T23:59`) - today) / 86400000),
        assessment: b.occChecklist || "OCC: active licensure + lifelong learning/CME + cognitive assessment + practice performance",
        notes: req.specReq ? `Specialty requirement: ${req.specReq}` : "",
        citation: `AOA OCC by-board CME table, ${code} (${b.name})`,
        verified: b.verified || null,
      });
    } else if (kind === "AOA-SUB" && AOA_OCC[code]) {
      // An AOA discipline certificate (e.g. Neurological Surgery) — its own
      // card, never combined with a "Surgery" pick. OCC is administered by
      // the parent board but the certificate and its annual discipline-
      // specific assessment stand alone.
      const b = AOA_OCC[code];
      const cyc = aoaCycle(today);
      const { req, firstCycle } = aoaRequirement(b, code, data, id, cyc);
      const from = `${cyc.start}-01-01`, to = `${cyc.end}-12-31`;
      const earned = hoursIn(cme, from, to);
      const cat1a = hoursIn(cme, from, to, c => (c.category || "").includes("AOA Category 1-A"));
      out.push({
        ...(firstCycle ? { firstCycle } : {}),
        id, source: "AOA", code: `${code}-${subName}`, name: subName,
        label: `${subName}, AOA`,
        from, to, countRule: null,
        required: req.hours, earned,
        met: earned >= req.hours && cat1a >= (req.cat1 || 0),
        cat1aRequired: req.cat1 || 0, cat1aEarned: cat1a,
        unit: "total hrs, all categories (OCC participant)",
        windowLabel: `${cyc.start}–${cyc.end} AOA cycle`,
        daysLeft: Math.ceil((new Date(`${cyc.end}-12-31T23:59`) - today) / 86400000),
        assessment: `Annual: unrestricted-license proof + discipline-specific 15-question open-book Longitudinal Assessment for ${subName} (80% = 12/15, $225/yr; completing it earns 5.0 Cat 1-B). Every 3 years: at least one QI/practice-performance attestation.`,
        notes: "Tracked as its own certificate, not combined with the parent surgery board.",
        citation: `AOA OCC by-board CME table, ${code} (${b.name}), ${subName} certificate`,
        verified: b.verified || null,
      });
    } else if (kind === "ABMS-SUB" || kind === "AOA-SUB" || kind === "UCNS" || kind === "ABPS") {
      out.push({
        id, source: kind, code, name: subName || code,
        label: subName ? `${subName} (${code})` : code,
        followsParent: true,
      });
    }
  }
  return out;
}

/**
 * Board specialty ids implied by the physician's LICENSE records: any license
 * whose type contains "Board Certification" is matched by board code (ABNS,
 * AOBS, ...) or full board name in its display name / notes. Returns ids in
 * the same "ABMS:CODE" / "AOA:CODE" shape Settings → Board Specialties uses,
 * so they can be unioned with data.settings.specialties and fed to
 * computeBoardCompliance. Codes win over names; among name matches only the
 * longest phrase counts ("Neurological Surgery" must not also match "Surgery").
 */
export function boardIdsFromLicenses(licenses) {
  const out = new Set();
  const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const hasPhrase = (text, phrase) => new RegExp(`(^|[^a-z0-9])${esc(phrase.toLowerCase())}([^a-z0-9]|$)`).test(text);
  const scan = (registry, kind, text) => {
    const codeHits = Object.keys(registry).filter(code => hasPhrase(text, code));
    if (codeHits.length) { codeHits.forEach(code => out.add(`${kind}:${code}`)); return; }
    const nameHits = Object.entries(registry)
      .filter(([, b]) => b.name && hasPhrase(text, b.name.replace(/&/g, "and")))
      .sort((a, b) => b[1].name.length - a[1].name.length);
    if (nameHits.length) out.add(`${kind}:${nameHits[0][0]}`);
  };
  for (const l of licenses || []) {
    const type = l.type || "";
    if (!/board certification/i.test(type)) continue;
    // An NCCPA or NP certification record is never name-scanned against the
    // physician boards: "PA-C, CAQ Emergency Medicine" must not demand ABEM
    // MOC hours. Its own card comes from certCompliance.js.
    if (certBodyOf(type)) continue;
    const text = `${l.name || ""} ${l.notes || ""}`.toLowerCase().replace(/&/g, "and");
    if (!text.trim()) continue;
    const isAOA = /\(AOA\)/i.test(type);
    const isABMS = /\(ABMS\)/i.test(type);
    if (isABMS || !isAOA) scan(ABMS_MOC, "ABMS", text);
    if (isAOA || !isABMS) scan(AOA_OCC, "AOA", text);
  }
  return [...out];
}

/**
 * The boards a physician's standing is computed for: the ones picked in
 * Settings plus the ones a Board Certification license record implies. Home
 * used the picks alone while the CME page added the license-implied ones, so
 * the two screens disagreed. A license-implied parent board (AOA:X, ABMS:X)
 * is dropped when Settings already holds a discipline or subspecialty of X:
 * a DO with an AOBS license and the Neurological Surgery discipline gets one
 * Neurological Surgery card, not an extra Surgery card.
 */
export function effectiveBoardSpecialties(data) {
  const picked = (data?.settings?.specialties || []).map(String);
  const hasChildOf = (kind, code) => picked.some(id => id.startsWith(`${kind}-SUB:${code}:`));
  const implied = boardIdsFromLicenses(data?.licenses).filter(id => {
    const [kind, code] = id.split(":");
    return !hasChildOf(kind, code);
  });
  return [...new Set([...picked, ...implied])];
}

/**
 * computeBoardCompliance over effectiveBoardSpecialties: what every screen
 * shows. Physician boards never apply to a PA or NP; their national
 * certification cards come from certCompliance.js.
 */
export function boardComplianceFor(data) {
  if (isAdvancedPractice(data?.settings?.degreeType)) return [];
  return computeBoardCompliance({ ...data, settings: { ...(data?.settings || {}), specialties: effectiveBoardSpecialties(data) } });
}

/**
 * The field on a Board Certification record that holds the physician's answer
 * to "Is <issued date> your first certification date?": "Yes" applies the
 * first-cycle proration, "No" (a recertification date) keeps the full hours.
 * Unanswered, the full hours stand and the card asks.
 */
export const FIRST_CYCLE_FIELD = "AOA first-cycle proration";

/**
 * The Board Certification record behind a board card (b.id is the Settings
 * id: "AOA:AOBS", "AOA-SUB:AOBS:Neurological Surgery", "ABMS:ABNS"): the
 * current record whose name or notes name that board, preferring one that
 * also names the discipline. Null when none is on file.
 */
export function boardRecordFor(licenses, boardId) {
  const [kind, code, ...rest] = String(boardId || "").split(":");
  const sub = rest.join(":").toLowerCase();
  const want = `${kind.replace(/-SUB$/, "")}:${code}`;
  const hits = (licenses || []).filter(l => l && !isInactive(l) && boardIdsFromLicenses([l]).includes(want));
  if (!hits.length) return null;
  const named = sub ? hits.find(l => `${l.name || ""} ${l.notes || ""}`.toLowerCase().includes(sub)) : null;
  return named || hits[0];
}

/**
 * An AOA card's hours for this cycle. A board that publishes a first-cycle
 * chart (BOARD_TASKS firstCycleProration, AOBS Component 2) owes a share of
 * its hours when the certificate was issued inside the current cycle: by the
 * half year of issue, rounded down to the nearest half hour. An issued date
 * can be a recertification date, so the share applies only once the
 * physician answers Yes on the record (FIRST_CYCLE_FIELD); unanswered or No,
 * the full hours stand. firstCycle.off is true whenever the share is not
 * applied (pending or No), so a reader that shows prorated hours only when
 * !off never shows a number the card is not using. A share of 0 is used only
 * where the chart publishes it (zeroNote); a 0 the chart does not state falls
 * back to the smallest published nonzero share.
 */
function aoaRequirement(b, code, data, id, cyc) {
  const base = b.timeLimited || { hours: 120, cat1: 0 };
  const chart = BOARD_TASKS[`AOA:${code}`]?.firstCycleProration;
  if (!chart) return { req: base, firstCycle: null };
  const rec = boardRecordFor(data.licenses, id);
  const issued = String(rec?.issuedDate || "").slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issued) || issued < `${cyc.start}-01-01` || issued > `${cyc.end}-12-31`) return { req: base, firstCycle: null };
  const half = (Number(issued.slice(0, 4)) - cyc.start) * 2 + (Number(issued.slice(5, 7)) >= 7 ? 1 : 0);
  const published = chart.shares[half];
  const nonzero = chart.shares.filter(x => x > 0);
  const minShare = nonzero.length ? Math.min(...nonzero) : 1;
  const zeroPublished = published === 0 && !!chart.zeroNote;
  const share = zeroPublished ? 0 : (published > 0 ? published : minShare);
  const hours = Math.floor(base.hours * share * 2) / 2;
  const cat1 = Math.floor((base.cat1 || 0) * share * 2) / 2;
  const raw = String(rec.customFields?.[FIRST_CYCLE_FIELD] ?? "").trim();
  const answer = /^no$/i.test(raw) ? "no" : /^yes$/i.test(raw) ? "yes" : null;
  const firstCycle = {
    issued, share, hours, fullHours: base.hours, url: chart.url, recordId: rec.id,
    off: answer !== "yes", pending: answer === null, answer,
    zeroNote: share === 0 ? chart.zeroNote : null,
    nextCycle: `${cyc.end + 1}-${cyc.end + 3}`,
    // The chart had no nonzero share for this half year and states no 0: the smallest one it does publish.
    minShareUsed: !(published > 0) && !zeroPublished,
  };
  return { req: answer === "yes" ? { ...base, hours, cat1 } : base, firstCycle };
}
